import {post,get} from '../api.js';
import {e,formValues,title,notify,state} from '../lib.js';
const authHead=(eyebrow,titleText,desc)=>`<div class="auth-story"><span class="eyebrow">${e(eyebrow)}</span><h1>${titleText}</h1><p>${e(desc)}</p><div class="auth-story-lines"><div>01 <span>بياناتك داخل حسابك</span></div><div>02 <span>الاشتراك وفق حالة السيرفر</span></div><div>03 <span>التفعيل يتطلب الموافقة</span></div></div><small>ONSTAR CLOUD / CUSTOMER ACCESS</small></div>`;
const field=(name,label,type='text',props='')=>`<label class="field"><span>${e(label)}</span><input name="${name}" type="${type}" required ${props}></label>`;
const buttons=(name,foot)=>`<button class="button primary full" type="submit" data-submit>${name}</button><p class="auth-foot">${foot}</p>`;
export function authView(path){let body='',h='';switch(path){
case '/register':title('إنشاء حساب OnStar Cloud');h=authHead('JOIN ONSTAR CLOUD','ابدأ علاقتك<br/><em>بشبكتك من هنا.</em>','أنشئ حسابًا جديدًا، وأكّد بريدك، ثم تابع الخدمة من لوحة المشترك.');body=`<h2>إنشاء حساب مشترك</h2><p>إنشاء الحساب لا يفعّل الخدمة تلقائيًا.</p><form id="register-form"><div class="auth-form-grid">${field('full_name','الاسم الكامل','text','autocomplete="name"')}${field('network_name','اسم الشبكة')}${field('email','البريد الإلكتروني','email','autocomplete="email" dir="ltr"')}${field('phone','رقم الهاتف','tel','autocomplete="tel" dir="ltr"')}<label class="field"><span>إصدار RouterOS</span><select name="routeros_version"><option value="7">RouterOS v7</option><option value="6">RouterOS v6</option></select></label>${field('password','كلمة المرور','password','minlength="8" autocomplete="new-password"')}${field('password_confirm','تأكيد كلمة المرور','password','minlength="8" autocomplete="new-password"')}</div>${buttons('إنشاء الحساب والمتابعة','لديك حساب؟ <a data-link href="/customer-login">تسجيل الدخول</a>')}</form>`;break;
case '/customer-login':title('دخول المشترك');h=authHead('WELCOME BACK','شبكتك بانتظارك.<br/><em>سجّل الدخول.</em>','استعد مساحتك الخاصة، وتابع اشتراكك وحالة الخدمة والأجهزة.');body=`<h2>تسجيل الدخول</h2><p>جلسة الدخول تُدار بواسطة السيرفر بشكل آمن.</p><form id="login-form">${field('email','البريد الإلكتروني','email','autocomplete="email" dir="ltr"')}${field('password','كلمة المرور','password','autocomplete="current-password"')}${buttons('دخول المشترك','ليس لديك حساب؟ <a data-link href="/register">إنشاء حساب</a>')}<a class="text-link" href="/forgot-password" data-link>هل نسيت كلمة المرور؟ ←</a></form>`;break;
case '/verify-email':title('تأكيد البريد');h=authHead('VERIFY YOUR ACCOUNT','خطوة صغيرة.<br/><em>حساب أكثر أمانًا.</em>','أدخل رمز التأكيد الذي وصلك من الخدمة إلى بريدك الإلكتروني.');body=`<h2>تأكيد البريد الإلكتروني</h2><p>استخدم رمز التحقق المرسل إلى بريدك.</p><form id="verify-form">${field('email','البريد الإلكتروني','email',`dir="ltr" value="${e(new URLSearchParams(location.search).get('email')||'')}"`)}${field('code','رمز التحقق','text','inputmode="numeric" pattern="[0-9]{6}" maxlength="6" dir="ltr" placeholder="000000"')}<button class="button primary full" data-submit>تأكيد البريد</button><button class="button dark-outline full" type="button" data-auth-action="resend">إرسال رمز جديد</button></form>`;break;
case '/forgot-password':title('استعادة كلمة المرور');h=authHead('ACCOUNT RECOVERY','استعد الوصول.<br/><em>بخطوات آمنة.</em>','أرسل طلب إعادة التعيين ثم أدخل الرمز الذي يصلك إلى بريدك.');body=`<h2>استعادة الحساب</h2><p>سوف تتلقى تعليمات الاستعادة عند إدخال بريد مسجّل.</p><form id="forgot-form">${field('email','البريد الإلكتروني','email','dir="ltr" autocomplete="email"')}<div id="reset-fields" hidden>${field('code','رمز الاستعادة','text','inputmode="numeric" pattern="[0-9]{6}" maxlength="6" dir="ltr"')}${field('new_password','كلمة المرور الجديدة','password','minlength="8" autocomplete="new-password"')}${field('confirm_password','تأكيد كلمة المرور','password','minlength="8" autocomplete="new-password"')}</div><button class="button primary full" data-submit>إرسال رمز الاستعادة</button></form>`;break;
}
return `<section class="auth-page"><div class="shell auth-layout">${h}<div class="auth-card"><div id="auth-feedback" role="status" aria-live="polite"></div>${body}</div></div></section>`}
export function authEvents(path,navigate){const card=document.querySelector('.auth-card');if(!card)return;const err=m=>{const fb=document.getElementById('auth-feedback');fb.textContent=m;fb.className='auth-feedback error';notify(m,'error')};const msg=m=>{const fb=document.getElementById('auth-feedback');fb.textContent=m;fb.className='auth-feedback success';notify(m)};let busy=false;async function perform(f,fn){if(busy)return;busy=true;const btn=f.querySelector('[data-submit]');if(btn)btn.disabled=true;try{await fn()}catch(ex){err(ex.message)}finally{busy=false;if(btn)btn.disabled=false}}
card.addEventListener('submit',ev=>{ev.preventDefault();const form=ev.target,v=formValues(form);
if(form.id==='login-form')perform(form,async()=>{const r=await post('/login',{email:v.email.trim(),password:v.password});if(r?.email_verified===false){navigate(`/verify-email?email=${encodeURIComponent(v.email.trim())}`);return}const me=await get('/me');state.me=me;state.meChecked=true;navigate('/account')});
if(form.id==='register-form')perform(form,async()=>{if(v.password!==v.password_confirm)throw new Error('كلمة المرور وتأكيدها غير متطابقين.');if(v.password.length<8)throw new Error('كلمة المرور 8 أحرف على الأقل.');const r=await post('/register',{full_name:v.full_name.trim(),network_name:v.network_name.trim(),email:v.email.trim(),phone:v.phone.trim(),routeros_version:v.routeros_version,password:v.password});navigate(`/verify-email?email=${encodeURIComponent(v.email.trim())}&sent=${r.email_sent?'1':'0'}`)});
if(form.id==='verify-form')perform(form,async()=>{await post('/email/verify',{email:v.email.trim(),code:v.code.trim()});msg('تم تأكيد البريد. سجّل الدخول إلى حسابك.');navigate('/customer-login')});
if(form.id==='forgot-form')perform(form,async()=>{if(document.getElementById('reset-fields').hidden){await post('/password/forgot',{email:v.email.trim()});document.getElementById('reset-fields').hidden=false;form.querySelector('[name=email]').readOnly=true;form.querySelector('[data-submit]').textContent='تعيين كلمة المرور';msg('إذا كان البريد مسجلًا فسيصلك رمز الاستعادة.')}
else{if(v.new_password!==v.confirm_password)throw new Error('كلمتا المرور غير متطابقتين');await post('/password/reset',{email:v.email.trim(),code:v.code.trim(),new_password:v.new_password});msg('تم تغيير كلمة المرور. يمكنك تسجيل الدخول.');navigate('/customer-login')}});
});
card.querySelector('[data-auth-action="resend"]')?.addEventListener('click',async()=>{const form=card.querySelector('form'),email=form.querySelector('[name=email]')?.value.trim();if(!email){err('أدخل البريد أولًا');return}try{const r=await post('/email/resend',{email});msg(r.email_sent===false?'تعذّر إرسال البريد حاليًا.':'تم إرسال طلب رمز جديد.') }catch(ex){err(ex.message)}});
}
